using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Globalization;
using System.Security;
namespace CircuitoStudio {
 public static class EngineeringReport {
  static string N(double x){return x.ToString("N3",CultureInfo.GetCultureInfo("pt-BR"));}
  static string NV(double? x){return x.HasValue?N(x.Value):"pendente";}
  static string E(string x){return SecurityElement.Escape(x??"");}
  static void AppendDynamics(string label,FaultDynamics value,StringBuilder text){if(value==null){text.AppendLine("Dinâmica 3F "+label+": pendente (impedância não disponível).");return;}text.AppendLine("Dinâmica 3F "+label+": FPcc="+N(value.PowerFactor)+"; kappa="+N(value.Kappa)+"; pico estimado ip="+N(value.PeakKA)+" kA; tau="+(value.Undamped?"sem amortecimento (R=0)":N(value.TimeConstantSeconds.Value*1000)+" ms")+"; envelope CC máximo em 10/20/100 ms="+N(value.DcEnvelopeKA(.01))+" / "+N(value.DcEnvelopeKA(.02))+" / "+N(value.DcEnvelopeKA(.1))+" kA.");}
  static void AppendFaultDynamics(CircuitResult row,StringBuilder text){AppendDynamics("no barramento de origem",row.FaultOriginDynamics,text);AppendDynamics("no fim do circuito",row.FaultEndDynamics,text);text.AppendLine("Pico: ip=sqrt(2)*kappa*Ik3; kappa=1,02+0,98*exp(-3R/X). Modelo radial R-L longe de geradores, sem limitação por proteção. tau=X/(2*pi*f*R); envelope CC máximo=sqrt(2)*Ik3*exp(-t/tau). Envelope CC é amplitude de offset possível, não corrente RMS, energia passante ou tempo de desligamento. A componente simétrica permanece constante neste modelo. Referência de pico: ABB Electrical installation handbook 2006, capítulo 6. https://library.e.abb.com/public/7a93440e8c790852c125716c0033f7a9/1SDC010002D0204.pdf");}
  static string Ohms(double? x){return x.HasValue?x.Value.ToString("G9",CultureInfo.GetCultureInfo("pt-BR")):"pendente";}
  static void AppendSource(Project p,StringBuilder text){var src=p.Source;var z=SourceNetwork.Calculate(src);text.AppendLine("Modelo da fonte: "+src.Model);
   if(src.Model==SourceModel.ImpedanciaDefinida){text.AppendLine("Impedância definida por fase R/X="+Ohms(src.DefinedPhaseROhm)+" / "+Ohms(src.DefinedPhaseXOhm)+" Ω; neutro R/X="+Ohms(src.DefinedNeutralROhm)+" / "+Ohms(src.DefinedNeutralXOhm)+" Ω; PE R/X="+Ohms(src.DefinedPEROhm)+" / "+Ohms(src.DefinedPEXOhm)+" Ω. Referência: "+src.NetworkReference);text.AppendLine(z.Detail);return;}
   if(src.Model==SourceModel.UPS){text.AppendLine("UPS: modo "+src.UPSMode+"; nominal "+N(src.UPSRatedKva)+" kVA; limite declarado do inversor "+N(src.UPSCurrentLimitKA)+" kA durante "+N(src.UPSCurrentLimitSeconds)+" s; zero significa desconhecido. Referência: "+src.NetworkReference);text.AppendLine("Modos são cenários separados; o programa não calcula transferência automática. Referência conceitual: Schneider Electric FAQ000280512. https://www.se.com/us/en/faqs/FAQ000280512/");if(src.UPSMode==UPSOperatingMode.Inversor){text.AppendLine(z.Detail);return;}}
   if(src.Model==SourceModel.GeradorSincrono){text.AppendLine("Gerador: "+N(src.GeneratorRatedKva)+" kVA; tensão "+N(src.LineVoltage)+" V; xd''="+N(src.GeneratorXdPercent)+"%; R="+Ohms(z.GeneratorROhm)+" Ω; Xd''="+Ohms(z.GeneratorXOhm)+" Ω; fonte dos dados: "+src.NetworkReference);text.AppendLine(z.Detail);text.AppendLine("Referência do modelo de reatância: Schneider Electric, Electrical Installation Guide, Generator protection, seção Subtransient phase. https://www.electrical-installation.org/enwiki/Generator_protection");return;}
   text.AppendLine("Base da corrente de curto: "+src.CurrentBasis+"; tensão da rede de entrada: "+(src.CurrentBasis==SourceCurrentBasis.RedeMT?src.UpstreamVoltageV:src.LineVoltage)+" V; fonte dos dados: "+src.NetworkReference);text.AppendLine("Impedâncias referidas à BT (ohm): rede R="+Ohms(z.NetworkROhm)+", X="+Ohms(z.NetworkXOhm)+"; transformador R="+Ohms(z.TransformerROhm)+", X="+Ohms(z.TransformerXOhm)+"; total R="+Ohms(z.TotalROhm)+", X="+Ohms(z.TotalXOhm));text.AppendLine(z.Detail);text.AppendLine("Método da alimentação: Zrede=c*Uentrada/(sqrt(3)*Irede); Zreferida=Zrede*(UBT/Uentrada)^2; Ztrafo=(uk/100)*UBT^2/Sn; Rtrafo=Pcu*UBT^2/Sn^2. I em A, Sn em VA, Pcu em W. Referência: ABB, The MV/LV transformer substations, seção 14.2 (p. 67–70). https://new.abb.com/docs/librariesprovider27/default-document-library/abb-transformerstations_ebook.pdf?sfvrsn=2");}
  public static string Memory(Project p,Study s){return Memory(p,s,null);}
  public static string Memory(Project p,Study s,System.Collections.Generic.ISet<string> selectedIds){
   if(p==null||s==null)throw new ArgumentNullException("project/study");
   if(selectedIds!=null&&selectedIds.Any(id=>!s.Circuits.Any(row=>row.Circuit.Id==id)))throw new InvalidDataException("Circuito selecionado não encontrado no estudo.");
   var rows=s.Circuits.Where(row=>selectedIds==null||selectedIds.Contains(row.Circuit.Id)).ToList();
   var text=new StringBuilder();text.AppendLine("OPENELETRIC 0.2 — MEMÓRIA DE CÁLCULO");text.AppendLine(p.Name+" | Cliente: "+p.Client+" | Responsável: "+p.Designer);text.AppendLine("Sistema: "+p.Earthing+"; "+p.Frequency+" Hz; fonte "+p.Source.LineVoltage+" V; modelo "+p.Source.Model+"; Ik rede informado "+p.Source.ShortCircuitKA+" kA; R/X rede "+p.Source.RXRatio+"; fator de tensão "+p.Source.VoltageFactor);
   text.AppendLine("Transformador: "+p.Source.TransformerKva+" kVA; uk "+p.Source.TransformerUkPercent+"%; perdas cobre "+p.Source.TransformerCopperLossKw+" kW.");text.AppendLine("Referência normativa informada: "+p.StandardReference);text.AppendLine("Anotação livre do método (não altera o algoritmo): "+p.CalculationMethod);text.AppendLine(CalculationManifest.Describe(p));text.AppendLine("TOTAIS (somente raízes; alimentadores não duplicam cargas)");text.AppendLine("P="+N(s.TotalKw)+" kW; Q="+N(s.TotalKvar)+" kvar; S="+N(s.TotalKva)+" kVA; FP="+N(s.PowerFactor));text.AppendLine("Corrente nominal por fase (L1/L2/L3): "+(s.PhaseCurrentKnown?N(s.PhaseCurrentA[0])+" / "+N(s.PhaseCurrentA[1])+" / "+N(s.PhaseCurrentA[2])+" A":"indisponível: tensão dos quadros/circuitos não corresponde à fonte"));text.AppendLine("Fases agregadas por P/Q; cargas trifásicas divididas igualmente entre fases. Sem análise de harmônicas, neutro, desequilíbrio de tensão ou sequência de fases.");text.AppendLine("Compensação teórica para FP "+p.Source.TargetPowerFactor+": "+N(s.CapacitorKvar)+" kvar. Sem análise de harmônicas/ressonância.");
   if(selectedIds!=null)text.AppendLine("ESCOPO DESTE RELATÓRIO: "+rows.Count+" de "+s.Circuits.Count+" circuitos selecionados. Os totais acima e a alimentação correspondem ao projeto completo; a seleção filtra os detalhes, sem alterar a rede ou recalcular cargas isoladas.");
   AppendSource(p,text);EnclosureCatalog.AppendReport(p,s,text,selectedIds);BusbarSelection.AppendReport(p,s,text,selectedIds);FaultExtremes.AppendReport(p,s.FaultExtremes,text,selectedIds);NetworkFlow.AppendReport(p,s,text,selectedIds);foreach(var motor in rows.Where(row=>row.MotorStarting!=null)){text.AppendLine("\r\nRENDIMENTO E PARTIDA DO MOTOR — "+motor.Circuit.Id);text.AppendLine(motor.MotorStarting.Detail);text.AppendLine("Referência dos métodos: Schneider Electric, Induction motors; Calculation of voltage drop in steady load conditions. https://www.electrical-installation.org/enwiki/Induction_motors ; https://www.electrical-installation.org/enwiki/Calculation_of_voltage_drop_in_steady_load_conditions");}text.AppendLine("Instalação / local: "+p.Site);for(int line=0;line<3;line++)text.AppendLine("Descrição — linha "+(line+1)+": "+p.DescriptionRows[line]);
   text.AppendLine("\r\nMÉTODOS\r\nI1=Pdem*1000/(V*FP); I3=Pdem*1000/(sqrt(3)*Vlinha*FP).\r\nPdem=Pentrada*FD; Q=Pdem*tan(acos(FP)); alimentadores usam a soma P+jQ a jusante.\r\nDeltaV=k*I*(R*cos(phi)+X*sin(phi))*L/n; k=2 ou sqrt(3); L em km.\r\nR derivada quando não informada: 23,7/S Cu ou 37,6/S Al (ohm/km, condição operacional).\r\nIz corrigida=Iz referência*Ftemperatura*Fagrupamento*n.\r\nCurto trifásico aproximado: Ik=c*U/(sqrt(3)*|Zfonte+Ztrafo+Zcabos|).\r\nGerador, se selecionado, usa a impedância inicial subtransitória declarada. Não inclui contribuição de motores, desequilíbrio real, todos os tipos de falta ou todos os fatores IEC60909.\r\nAdiabático: Smin=sqrt(I²t)/k; I²t deve ser dado do equipamento.\r\nTT: Ra*IdeltaN<=UL; TN: Zs*Ia<=U0 são verificações parciais, sem prova de tempo.\r\n0 nos dados opcionais significa desconhecido, não resultado aprovado.");
   foreach(var row in rows)if(row.Circuit.CurveStudy!=null){var pair=row.Circuit.CurveStudy;text.AppendLine("\r\nCURVAS ANEXADAS — "+row.Circuit.Id);text.AppendLine("Montante: "+(pair.Upstream==null?"não informado":pair.Upstream.Source+"; "+pair.Upstream.Points.Count+" pontos"));text.AppendLine("Jusante: "+(pair.Downstream==null?"não informado":pair.Downstream.Source+"; "+pair.Downstream.Points.Count+" pontos"));var comparison=CurveMath.Compare(pair.Upstream,pair.Downstream);text.AppendLine(comparison.Status+". "+comparison.Detail);text.AppendLine("Envelopes informados no estudo deste circuito; não inferem vínculo certificado entre dispositivos reais.");}
   foreach(var row in rows)if(row.Circuit.ProtectionResponses!=null)text.AppendLine(ProtectionResponses.Describe(p,row.Circuit));
   foreach(var row in rows)if(row.Circuit.DriveMotor!=null)text.AppendLine(row.Circuit.DriveMotor.Describe(row.Circuit));
   foreach(var r in rows){var c=r.Circuit;var a=c.Cable;var pr=c.Protection;text.AppendLine("\r\n────────────────────────────────────────────────────────────");text.AppendLine(r.Board.Name+" / "+c.Id+" — "+c.Name+" ["+c.Kind+"]");text.AppendLine("Quadro destino: "+(c.ChildBoardId==""?"carga terminal":c.ChildBoardId)+"; fases "+c.Phases+"; atribuição "+c.PhaseLabel+"; V="+c.Voltage+"; Pentrada="+c.PowerKw+" kW; FP="+c.PowerFactor+"; FD="+c.DemandFactor);text.AppendLine("Pdem="+N(r.DemandKw)+" kW; Q="+N(r.ReactiveKvar)+" kvar; Ib="+N(r.CurrentA)+" A");text.AppendLine("Limite de queda acumulada do circuito: "+N(c.VoltageDropLimitPercent??p.Source.MaxDropPercent)+"% ("+(c.VoltageDropLimitPercent.HasValue?"definido no circuito":"herdado do projeto")+").");text.AppendLine("Cabo "+a.Material+" / "+a.Insulation+"; S="+c.CableMm2+" mm²; L="+c.LengthM+" m; n="+a.Parallel+"; método="+a.InstallationMethod);text.AppendLine("Condições/fatores de correção: "+CableFactors.Describe(c));text.AppendLine("Referência cabo: "+a.Reference+"; R informada="+a.ResistanceOhmKm+" ohm/km; X="+a.ReactanceOhmKm+" ohm/km; Izbase="+a.AmpacityA+" A; Ft="+a.TemperatureFactor+"; Fg="+a.GroupingFactor);text.AppendLine("Iz corrigida="+NV(r.CorrectedAmpacityA)+" A; queda local="+(r.VoltageDropKnown?N(r.VoltageDropV)+" V / "+N(r.VoltageDropPercent)+"%":"pendente")+"; acumulada="+(r.AccumulatedDropKnown?N(r.AccumulatedDropPercent)+"%":"pendente"));text.AppendLine("Curto 3F origem/fim="+NV(r.FaultOriginKA)+" / "+NV(r.FaultEndKA)+" kA; curto 2F origem/fim="+NV(r.FaultTwoPhaseOriginKA)+" / "+NV(r.FaultTwoPhaseEndKA)+" kA; aproximação simétrica de sequência positiva/negativa, sem mínimo/máximo normativo.");text.AppendLine("Corrente fase-terra por Zs informado="+NV(r.FaultLoopKA)+" kA. Resultado condicionado ao laço Zs completo e tensão fase-neutro declarados.");text.AppendLine("Seção adiabática mínima="+NV(r.AdiabaticMinMm2)+" mm²");text.AppendLine("Proteção In="+c.BreakerA+" A; interrupção declarada="+pr.BreakingCapacityKA+" kA; I2="+pr.ConventionalTripA+" A; I²t="+pr.LetThroughA2s+" A²s; tempo informado="+pr.DisconnectSeconds+" s");FaultTimeTrace.AppendReport(p,c,text);if(p.Source.SupportsConstantImpedanceWaveform)AppendFaultDynamics(r,text);else text.AppendLine("Dinâmica temporal desta fonte: pendente. Gerador não usa onda R-L estacionária; UPS inversor não é fonte de tensão não limitada.");foreach(var check in s.Checks.Where(x=>x.CircuitId==c.Id))text.AppendLine("["+check.Status+"] "+check.Rule+": "+check.Detail);text.AppendLine("Referências e notas do circuito: "+c.Notes);text.AppendLine("Hipóteses: "+r.Assumptions);}
   text.AppendLine("\r\nFONTES DOS MÉTODOS\r\nhttps://www.electrical-installation.org/enwiki/Calculation_of_voltage_drop_in_steady_load_conditions\r\nhttps://www.electrical-installation.org/enwiki/Practical_values_for_a_protective_scheme\r\nhttps://www.electrical-installation.org/enwiki/Verification_of_the_withstand_capabilities_of_cables_under_short-circuit_conditions\r\nhttps://www.electrical-installation.org/enwiki/TT_system_-_Principle\r\nhttps://www.electrical-installation.org/enwiki/Theoretical_principles_to_improve_power_factor\r\nMétodos implementados de forma independente. Resultados e pendências exigem revisão do projetista; não constituem certificação normativa.");return text.ToString();
  }
  public static void Html(Project p,string path){
   var study=Engineering.Analyze(p);Exports.Html(p,path);string html=File.ReadAllText(path);html=html.Replace("sem verificação de capacidade, queda de tensão, curto-circuito, seletividade ou normas","verificações disponíveis na memória abaixo, sem declaração de conformidade normativa");
   var section=new StringBuilder("<h2>Estudos elétricos — resultados e pendências</h2><p>Potências agregadas sem duplicar alimentadores. Consulte hipóteses e dados de referência na memória.</p><table><thead><tr><th>Circuito</th><th>Ib A</th><th>Queda acumulada %</th><th>Ik 3F origem kA</th><th>Ik 3F fim kA</th><th>Ik 2F aprox. origem kA</th><th>Ik 2F aprox. fim kA</th><th>I laço terra kA</th><th>Iz A</th></tr></thead><tbody>");foreach(var r in study.Circuits){section.Append("<tr><td>").Append(E(r.Circuit.Id+" · "+r.Circuit.Name)).Append("</td><td>").Append(N(r.CurrentA)).Append("</td><td>").Append(r.AccumulatedDropKnown?N(r.AccumulatedDropPercent):"pendente").Append("</td><td>").Append(NV(r.FaultOriginKA)).Append("</td><td>").Append(NV(r.FaultEndKA)).Append("</td><td>").Append(NV(r.FaultTwoPhaseOriginKA)).Append("</td><td>").Append(NV(r.FaultTwoPhaseEndKA)).Append("</td><td>").Append(NV(r.FaultLoopKA)).Append("</td><td>").Append(NV(r.CorrectedAmpacityA)).Append("</td></tr>");}section.Append("</tbody></table><h2>Memória completa</h2><pre style=\"white-space:pre-wrap;overflow-wrap:anywhere;font-size:11px\">").Append(E(Memory(p,study))).Append("</pre>");html=html.Replace("</main>",section+"</main>");File.WriteAllText(path,html,new UTF8Encoding(false));
  }
  static string Cell(string s){s=s??"";string trimmed=s.TrimStart();if((trimmed.Length>0&&"=+-@".IndexOf(trimmed[0])>=0)||(s.Length>0&&(s[0]=='\t'||s[0]=='\r'||s[0]=='\n')))s="'"+s;return "\""+s.Replace("\"","\"\"")+"\"";}
  static void AppendDriveMaterials(Project p,StringBuilder s){foreach(var b in p.Boards)foreach(var c in b.Circuits)if(c.DriveMotor!=null){var d=c.DriveMotor;s.AppendLine(String.Join(";",new[]{"Inversor",b.Name,c.Id,"Entrada "+N(d.InputRatedA)+" A; saída "+N(d.OutputRatedA)+" A / "+N(d.OutputVoltageV)+" V","1","un",d.DriveReference+"; fonte: "+d.Source}.Select(Cell)));s.AppendLine(String.Join(";",new[]{"Motor associado",b.Name,c.Id,N(d.MotorShaftKw)+" kW de eixo; "+N(d.MotorRatedA)+" A / "+N(d.MotorVoltageV)+" V","1","un",d.MotorReference+"; fonte: "+d.Source}.Select(Cell)));}}
  public static void Materials(Project p,string path){p.Validate();var s=new StringBuilder("Categoria;Quadro;Circuito;Descrição;Quantidade;Unidade;Referência\r\n");foreach(var b in p.Boards){s.AppendLine(string.Join(";",new[]{"Quadro",b.Name,"",b.Enclosure.WidthMm+" x "+b.Enclosure.HeightMm+" mm","1","un",b.Enclosure.Manufacturer+" "+b.Enclosure.Reference}.Select(Cell)));foreach(var c in b.Circuits){s.AppendLine(string.Join(";",new[]{"Rota de cabo",b.Name,c.Id,c.Cable.Material+" "+c.Cable.Insulation+" "+c.CableMm2+" mm²; "+c.Cable.Parallel+" paralelos",c.LengthM.ToString(CultureInfo.GetCultureInfo("pt-BR")),"m de rota",c.Cable.Reference}.Select(Cell)));if(c.BreakerA>0)s.AppendLine(string.Join(";",new[]{"Proteção",b.Name,c.Id,c.BreakerA+" A / "+c.Protection.BreakingCapacityKA+" kA","1","un",c.Notes}.Select(Cell)));if(c.SwitchgearSelection!=null){var device=c.SwitchgearSelection.Rating;s.AppendLine(string.Join(";",new[]{device.IsFuse?"Conjunto de fusíveis selecionado":"Seccionador selecionado",b.Name,c.Id,device.Family+"; "+BreakerSelection.PoleName(device.Poles)+"; "+device.RatedA+" A","1","conjunto",device.Manufacturer+" / "+device.Reference+"; fonte "+device.Source+"; versão "+device.DataVersion}.Select(Cell)));}if(c.ResidualSelection!=null){var residual=c.ResidualSelection.Rating;s.AppendLine(string.Join(";",new[]{"Conjunto diferencial selecionado",b.Name,c.Id,residual.Kind+"; tipo "+residual.Waveform+"; "+residual.RatedA+" A; "+residual.DeltaMilliA+" mA","1","conjunto",residual.Manufacturer+" / "+residual.Reference+"; sensor "+residual.SensorReference+"; atuador "+residual.ActuatorReference+"; acessório "+residual.AccessoryReference+"; fonte "+residual.Source+"; versão "+residual.DataVersion}.Select(Cell)));}if(c.ReturnSizing!=null){foreach(var conductor in new[]{c.ReturnSizing.Neutral,c.ReturnSizing.Protective}.Where(item=>item!=null))s.AppendLine(string.Join(";",new[]{"Condutor de retorno selecionado",b.Name,c.Id,conductor.Role+"; "+conductor.Material+"; "+conductor.SectionMm2+" mm²",c.LengthM.ToString(CultureInfo.GetCultureInfo("pt-BR")),"m de condutor",conductor.Reference+"; fonte "+conductor.Source+"; versão "+conductor.DataVersion+"; condições "+conductor.Conditions}.Select(Cell)));}if(c.MotorStarterSelection!=null){var starter=c.MotorStarterSelection.Rating;s.AppendLine(string.Join(";",new[]{"Conjunto de partida selecionado",b.Name,c.Id,starter.Kind+"; "+starter.Service+"; classe "+starter.TripClass+"; ajuste "+starter.ThermalSettingA+" A","1","conjunto",starter.Manufacturer+" / "+starter.Reference+"; controlador "+starter.ControllerReference+"; térmico "+starter.OverloadReference+"; fonte "+starter.Source+"; versão "+starter.DataVersion}.Select(Cell)));}}}AppendDriveMaterials(p,s);s.AppendLine(Cell("Comprimento é rota, sem multiplicar condutores/fases/PE ou folgas. Lista não representa quantitativo executivo completo."));File.WriteAllText(path,s.ToString(),new UTF8Encoding(true));}
 }
